-- Demo data for the local stack.
--
-- Runs after the backend reports healthy, because Hibernate creates the schema
-- on startup (ddl-auto=update) and there is nothing to insert into before that.
--
-- Every row belongs to the dev user seeded in deploy/local/keycloak-realm.json,
-- which is also the ADMIN_USER_LIST entry in compose.yaml. That is what makes
-- these appear as shared reference data rather than one user's private entries.
--
-- Ids are explicit so rows can reference each other. The id columns are
-- GENERATED BY DEFAULT AS IDENTITY, so that is allowed, and the sequences are
-- moved past the seeded rows at the end so the application cannot collide.
--
-- Safe to run repeatedly. Reference/design rows are refreshed where the local visual demo
-- depends on them; transactional rows remain ON CONFLICT DO NOTHING, so saved_drinks dates
-- below are frozen at whatever CURRENT_DATE was on the first run. On a
-- long-lived volume the demo history ages; `docker-compose down -v` gives
-- you fresh dates. It also means a demo row deleted through the UI comes
-- back on the next start.

BEGIN;

-- The dev user from the Keycloak realm import.
\set dev_user '423c91e4-491f-4f82-aba6-3c982857e0e4'

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, field = EXCLUDED.field,
  ink_dark = EXCLUDED.ink_dark, ink_light = EXCLUDED.ink_light;

-- The four silhouettes used by the demo recommendations. Production can keep the full catalogue.
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, g = EXCLUDED.g, l = EXCLUDED.l, f = EXCLUDED.f;

ON CONFLICT (id) DO NOTHING;

-- Beer must be id 4. The backend's BEER_ID property defaults to 4 and decides
-- which type gets brand and flavour handling.
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

-- Default recommendations. DefaultRecommendationSource serves these to every
-- user, because the owner is in ADMIN_USER_LIST.
ON CONFLICT (id) DO UPDATE SET
  color_palette_id = EXCLUDED.color_palette_id,
  glassware_id = EXCLUDED.glassware_id;

-- Recent history, so the history page has content and
-- DynamicPersonalRecommendationSource has something to decay. The date column
-- is a varchar holding an ISO date, which is what the application writes.
ON CONFLICT (id) DO NOTHING;

-- Hand the identity columns back to the application.
SELECT setval(pg_get_serial_sequence('alcohol_volumes',   'id'), COALESCE((SELECT MAX(id) FROM alcohol_volumes),   1));
SELECT setval(pg_get_serial_sequence('alcohol_types',     'id'), COALESCE((SELECT MAX(id) FROM alcohol_types),     1));
SELECT setval(pg_get_serial_sequence('alcohol_subtypes',  'id'), COALESCE((SELECT MAX(id) FROM alcohol_subtypes),  1));
SELECT setval(pg_get_serial_sequence('consumption_types', 'id'), COALESCE((SELECT MAX(id) FROM consumption_types), 1));
SELECT setval(pg_get_serial_sequence('brands',            'id'), COALESCE((SELECT MAX(id) FROM brands),            1));
SELECT setval(pg_get_serial_sequence('beer_flavours',     'id'), COALESCE((SELECT MAX(id) FROM beer_flavours),     1));
SELECT setval(pg_get_serial_sequence('recommendations',   'id'), COALESCE((SELECT MAX(id) FROM recommendations),   1));
SELECT setval(pg_get_serial_sequence('saved_drinks',      'id'), COALESCE((SELECT MAX(id) FROM saved_drinks),      1));
SELECT setval(pg_get_serial_sequence('color_palettes',    'id'), COALESCE((SELECT MAX(id) FROM color_palettes),    1));
SELECT setval(pg_get_serial_sequence('glassware',         'id'), COALESCE((SELECT MAX(id) FROM glassware),         1));

COMMIT;
